const isForm = $input.first().json.Niche !== undefined;
if (isForm) return [{json:{niche:$input.first().json.Niche,location:$input.first().json.Location}}];
return $input.all().filter(i=>i.json.Status==='Active').map(i=>({json:{niche:i.json.Niche,location:i.json.Location}}));

const runId=$input.first().json.data.id;
const token=$env.APIFY_TOKEN;
const maxTries=parseInt($env.MAX_APIFY_POLL_ATTEMPTS)||15;
const cfg=$('Split Config Rows').first().json;
for(let i=0;i<maxTries;i++){
  const res=await this.helpers.request({method:'GET',url:`https://api.apify.com/v2/actor-runs/${runId}?token=${token}`,json:true});
  const s=res.data.status;
  if(s==='SUCCEEDED') return [{json:{datasetId:res.data.defaultDatasetId,status:'done',niche:cfg.niche,location:cfg.location}}];
  if(s==='FAILED'||s==='ABORTED') return [{json:{status:'failed',error:`Apify run ${s}`}}];
  await new Promise(r=>setTimeout(r,10000));
}
return [{json:{status:'timeout',error:'Apify poll timeout — increase MAX_APIFY_POLL_ATTEMPTS'}}];

const seen=new Set();
const leads=[];
const meta=$('Poll Apify Maps Run').first().json;
for(const item of $input.all().map(i=>i.json)){
  const url=(item.website??'').toLowerCase().replace(/\/$/,'').trim();
  if(!url||seen.has(url))continue;
  seen.add(url);
  let domain='';
  try{domain=new URL(url).hostname.replace(/^www\./,'');}catch{}
  leads.push({json:{niche:meta.niche,location:meta.location,runId:$workflow.vars.runId,
    company:item.title??item.name??'',url,domain,
    phone:item.phone??'',address:item.address??'',
    rating:item.totalScore??null,reviewsCount:item.reviewsCount??0,
    email:item.email??item.emails?.[0]??null,
    facebook:item.facebook??null,instagram:item.instagram??null,linkedin:item.linkedin??null}});
}
$workflow.vars.totalFetched=leads.length;
return leads;

const existing=new Set($('Read All Existing URLs').all()
  .map(i=>(i.json.URL??i.json.url??'').toLowerCase().replace(/\/$/,''))
  .filter(Boolean));
const fresh=$input.all().filter(i=>{
  const url=(i.json.url??'').toLowerCase().replace(/\/$/,'');
  return url&&!existing.has(url);
});
const skipped=$input.all().length-fresh.length;
$workflow.vars.skippedDups=($workflow.vars.skippedDups??0)+skipped;
if(fresh.length===0) return [{json:{noNewLeads:true,niche:$input.first()?.json?.niche??'',
  message:`All ${skipped} results already in Sheets. Add a new location or niche.`}}];
return fresh;

const provider = $env.LLM_PROVIDER ?? 'deepseek';
const apiKey = $env.LLM_API_KEY;
const model = $env.LLM_MODEL;
const system = $input.first().json.system;
const prompt = $input.first().json.prompt;
const maxTok = parseInt($input.first().json.max_tokens) || 800;
const passthrough = $input.first().json;
let url, headers, body;
if (provider === 'anthropic') {
  url = 'https://api.anthropic.com/v1/messages';
  headers = {'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json'};
  body = {model, max_tokens: maxTok, system, messages: [{role: 'user', content: prompt}]};
} else {
  url = $env.LLM_BASE_URL;
  headers = {'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json'};
  body = {model, max_tokens: maxTok, messages: [{role: 'system', content: system}, {role: 'user', content: prompt}]};
}
return [{json: {url, headers, body, passthrough}}];

const provider=$env.LLM_PROVIDER??'deepseek';
const data=$input.first().json;
let text=provider==='anthropic'?(data.content?.[0]?.text??''):(data.choices?.[0]?.message?.content??'');
text=text.replace(/^```(?:json)?\n?/,'').replace(/\n?```$/,'').trim();
let industryOverview;
try{industryOverview=JSON.parse(text);}catch{industryOverview={error:'parse_failed',outreach_angle:'digital modernisation'};}
$workflow.vars.industryOverview=industryOverview;
return [{json:{industryOverview,niche:$input.first().json.passthrough?.pt_niche,location:$input.first().json.passthrough?.pt_location}}];

const d=$input.first().json;
const cats=d.lighthouseResult?.categories??{};
const audits=d.lighthouseResult?.audits??{};
const lead=$('Split Leads for Enrichment').first().json;
return [{json:{...lead,
  perfScore:Math.round((cats.performance?.score??0)*100),
  seoAuditScore:Math.round((cats.seo?.score??0)*100),
  lcp:audits['largest-contentful-paint']?.displayValue??null,
  hasHTTPS:(d.id??'').startsWith('https')}}];

const r=$input.first().json?.response?.[0]??{};
const ps=$('Extract PageSpeed Data').first().json;
return [{json:{...ps,pageRank:r.page_rank_integer??null}}];

