const provider=$env.LLM_PROVIDER??'deepseek';
const data=$input.first().json;
const lead=JSON.parse($input.first().json.passthrough?.lead_passthrough??'{}');
let text=provider==='anthropic'?(data.content?.[0]?.text??''):(data.choices?.[0]?.message?.content??'');
text=text.replace(/^```(?:json)?\n?/,'').replace(/\n?```$/,'').trim();
let score;
try{score=JSON.parse(text);if(typeof score.total!=='number')throw new Error('missing total');}
catch(e){score={tech_score:0,seo_score:0,brand_score:0,sales_readiness:0,expansion_score:0,total:0,
  is_local_business:'Unknown',top_3_flaws:['Score parse failed'],opportunity_summary:'Review manually',
  recommended_first_service:'Unknown',expansion_opportunities:[],expansion_reasoning:'',parseError:true};
  $workflow.vars.errorCount=($workflow.vars.errorCount??0)+1;}
$workflow.vars.processedCount=($workflow.vars.processedCount??0)+1;
return [{json:{...lead,...score}}];

const store=$workflow.vars.scoredLeads??[];
store.push($input.first().json);
$workflow.vars.scoredLeads=store;
const totalFetched=$workflow.vars.totalFetched??store.length;
if(store.length<totalFetched)return[];
const topN=parseInt($env.TOP_LEADS_KEPT)||10;
const ranked=store.filter(l=>typeof l.total==='number').sort((a,b)=>{
  if(b.total!==a.total)return b.total-a.total;
  const aL=a.is_local_business==='Yes'?1:0,bL=b.is_local_business==='Yes'?1:0;
  if(bL!==aL)return bL-aL;
  return(b.expansion_score??0)-(a.expansion_score??0);
});
const top=ranked.slice(0,topN);
$workflow.vars.totalScored=ranked.length;
$workflow.vars.localCount=top.filter(l=>l.is_local_business==='Yes').length;
$workflow.vars.scoredLeads=[];
$workflow.vars.totalFetched=0;
return top.map(l=>({json:l}));

